// Generate an AML / ID verification checklist based on business type
const row = $input.first().json;
const type = row.businessType;

let idItems = ['Photo ID (passport or driving licence)', 'Proof of address dated within the last 3 months'];
if (type === 'Limited Company' || type === 'LLP') {
  idItems = idItems.concat([
    'Certificate of Incorporation',
    'Register of Directors / PSCs (People with Significant Control)',
    'ID and proof of address for each director/PSC holding 25%+ ownership or control'
  ]);
} else if (type === 'Partnership') {
  idItems.push('ID and proof of address for each partner');
}

const amlChecklist = [
  'Complete client risk assessment (source of funds / source of wealth as applicable)',
  ...idItems,
  'Screen client against sanctions and PEP (Politically Exposed Persons) lists',
  'Record AML checks on file per firm AML policy and MLR 2017 (as amended) requirements',
  'Confirm no conflicts of interest with existing clients'
];

return [{
  json: {
    ...row,
    amlChecklist
  }
}];
